  'Accounts used by posting can be renamed but not turned off. An account with a balance can be turned off only after moving its balance.': 'الحسابات المستخدمة في الترحيل يمكن إعادة تسميتها لكن لا يمكن إيقافها. والحساب الذي له رصيد لا يمكن إيقافه إلا بعد نقل رصيده.',

