  ', which your accountant later moves to capital or retained earnings.': '، والتي ينقلها محاسبك لاحقاً إلى رأس المال أو الأرباح المحتجزة.',
  'Opening date': 'تاريخ الافتتاح',
  'Opening balances were already entered. Anything you add now adds to them; to undo a mistake, reverse its journal voucher or void its opening document.': 'تم إدخال الأرصدة الافتتاحية من قبل. أي شيء تضيفه الآن يُضاف إليها؛ ولتصحيح خطأ اعكس قيد اليومية أو ألغِ المستند الافتتاحي.',
  '1. Cash, bank and other balances': '١. النقدية والبنوك والأرصدة الأخرى',
  'Positive means the account’s usual side: what you have (cash, bank, fixed assets) or what you owe (loans, VAT payable).': 'الموجب يعني الجانب المعتاد للحساب: ما تملكه (نقدية، بنك، أصول ثابتة) أو ما عليك (قروض، ضريبة مستحقة).',
  'Post these balances': 'ترحيل هذه الأرصدة',
  '2. What customers owe you and what you owe suppliers': '٢. ما يستحق لك على العملاء وما يستحق عليك للموردين',
  'One line per customer or supplier. Each becomes an opening document you can later receive or pay against, and it shows in their balance and ageing.': 'سطر لكل عميل أو مورد. يصبح كل منها مستنداً افتتاحياً يمكنك لاحقاً التحصيل أو السداد عليه، ويظهر في رصيده وأعمار ديونه.',
