  'Adjust stock': 'تسوية المخزون',
  'Stock count': 'جرد المخزون',
  'For damage, loss, samples or stock found. Use + to add and − to take away. Removals are valued at average cost and go to 5900 Inventory adjustments.': 'للتالف أو المفقود أو العينات أو المخزون الذي وُجد. استخدم + للإضافة و− للخصم. يُقيّم المخصوم بمتوسط التكلفة ويذهب إلى ٥٩٠٠ تسويات المخزون.',
