  'Type what you counted. Only the products you fill in are changed; each difference is adjusted under one count number.': 'اكتب ما قمت بجرده. تتغير فقط المنتجات التي تملؤها؛ وتُسوّى كل الفروق تحت رقم جرد واحد.',
