  /* ---------- accounting: closing the books ---------- */
  'The books are closed up to {date}. Nothing can be posted on or before that date.': 'الدفاتر مقفلة حتى {date}. لا يمكن ترحيل أي شيء في هذا التاريخ أو قبله.',
  'Closed years: {years}.': 'السنوات المقفلة: {years}.',
  'No period is closed yet. Close each month once its documents are in, so last month’s figures can’t change by accident.': 'لم تُقفل أي فترة بعد. أقفل كل شهر بعد إدخال مستنداته، حتى لا تتغير أرقام الشهر الماضي بالخطأ.',
  'Month-end close': 'إقفال نهاية الشهر',
  'Every month that has ended is already closed.': 'كل شهر انتهى تم إقفاله بالفعل.',
  'Month': 'الشهر',
  'Close {month}? Nothing dated on or before its last day can be posted afterwards; only an admin can reopen it.': 'إقفال {month}؟ لن يمكن بعد ذلك ترحيل أي شيء بتاريخ آخر يوم فيه أو قبله؛ والمسؤول فقط يمكنه إعادة فتحه.',
  '{month} closed': 'تم إقفال {month}',
  'Close {month}': 'إقفال {month}',
  'Fix the red items first.': 'أصلح البنود الحمراء أولاً.',
  'Year-end close': 'إقفال نهاية العام',
  'Moves the year’s income and expenses to 3100 Retained earnings in one closing entry dated 31 December, then locks the year. Income and expense accounts start the new year at zero; the balance sheet keeps the profit in equity.': 'ينقل إيرادات ومصروفات العام إلى ٣١٠٠ الأرباح المحتجزة في قيد إقفال واحد بتاريخ ٣١ ديسمبر، ثم يقفل العام. تبدأ حسابات الإيرادات والمصروفات العام الجديد من الصفر، وتحتفظ الميزانية بالربح في حقوق الملكية.',
  'No ended year is waiting to be closed.': 'لا يوجد عام منتهٍ بانتظار الإقفال.',
  'Year': 'العام',
  'Expenses (cost of goods included)': 'المصروفات (شاملة تكلفة البضاعة)',
  'Profit to retained earnings': 'الربح إلى الأرباح المحتجزة',
  'Loss to retained earnings': 'الخسارة إلى الأرباح المحتجزة',
  'Can’t close yet: {problems}.': 'لا يمكن الإقفال بعد: {problems}.',
  'Close {year}? A closing entry moves {amount} to retained earnings and the books lock up to {date}.': 'إقفال {year}؟ ينقل قيد الإقفال {amount} إلى الأرباح المحتجزة وتُقفل الدفاتر حتى {date}.',
  '{year} closed': 'تم إقفال {year}',
