  'Reopen the books after {date}?': 'إعادة فتح الدفاتر بعد {date}؟',
  'Closed years in that range have their closing entry reversed.': 'السنوات المقفلة في هذه الفترة سيُعكس قيد إقفالها.',
  'This is recorded in the audit trail with your reason.': 'يُسجّل ذلك في سجل التدقيق مع السبب الذي كتبته.',
  'Books reopened': 'تمت إعادة فتح الدفاتر',
  'Reopen (admin)': 'إعادة الفتح (للمسؤول)',
  'Only for a real correction, e.g. a supplier bill found after the close. Choose the last day that stays closed; everything after it opens again.': 'فقط لتصحيح حقيقي، مثل فاتورة مورد ظهرت بعد الإقفال. اختر آخر يوم يبقى مقفلاً؛ وكل ما بعده يُفتح من جديد.',
