  'The documents agree with the VAT accounts (2200 and 1400) for this month.': 'المستندات مطابقة لحسابات ضريبة القيمة المضافة (٢٢٠٠ و١٤٠٠) لهذا الشهر.',
  'The VAT accounts show output {output} and input {input}, which differ from the documents. Contact support before filing.': 'حسابات الضريبة تُظهر مخرجات {output} ومدخلات {input}، وهي تختلف عن المستندات. تواصل مع الدعم قبل تقديم الإقرار.',
  'Invoices of {month} without an e-invoice number: {n}': 'فواتير {month} بدون رقم فاتورة إلكترونية: {n}',
