  'Check the rows': 'افحص الصفوف',
  'Check the rows first': 'افحص الصفوف أولًا',
  'Saving part {a} of {b}… Keep this window open.': 'جارٍ حفظ الجزء {a} من {b}… اترك هذه النافذة مفتوحة.',
  '{a} added and {b} updated.': 'أُضيف {a} وحُدّث {b}.',
  'The import stopped before the end. The parts already saved are kept; you can undo them below.': 'توقف الاستيراد قبل نهايته. الأجزاء التي حُفظت باقية؛ ويمكنك التراجع عنها بالأسفل.',
  'Undo this import': 'تراجع عن هذا الاستيراد',
  'Old system id: {id}': 'المعرّف في النظام القديم: {id}',
