  'This Excel file uses a kind of compression that can’t be read here. Save it again from Excel, or as CSV.': 'ملف الإكسل هذا يستخدم نوع ضغط لا يمكن قراءته هنا. احفظه مرة أخرى من إكسل، أو بصيغة CSV.',
  // H2: opening books
  '{a}: enter an amount': '{a}: أدخل مبلغًا',
  'Choose the go-live date first': 'اختر تاريخ بدء العمل أولًا',
  'The opening balances are final since going live. An admin can reopen them.': 'الأرصدة الافتتاحية نهائية منذ بدء العمل. يمكن للمسؤول إعادة فتحها.',
  'Choose the go-live date': 'اختر تاريخ بدء العمل',
  'The go-live date can be tomorrow at the latest: the opening balances are the ones at the end of the day before': 'يمكن أن يكون تاريخ بدء العمل غدًا على الأكثر: الأرصدة الافتتاحية هي أرصدة نهاية اليوم السابق',
  'Clear the steps already entered before changing the go-live date': 'امسح الخطوات المُدخلة قبل تغيير تاريخ بدء العمل',
  'set the go-live date to {a}': 'حدّد تاريخ بدء العمل {a}',
  'Cheque {a} was already cashed, so it can’t be taken out of the opening balances': 'تم صرف الشيك {a} بالفعل، لذلك لا يمكن إخراجه من الأرصدة الافتتاحية',
  '{a} has stock movements since its opening stock, so the opening stock can’t be taken out. Adjust the stock instead.': '{a} له حركات مخزون بعد رصيده الافتتاحي، لذلك لا يمكن إخراج المخزون الافتتاحي. سوِّ المخزون بدلًا من ذلك.',
  'cleared the opening {a}': 'مسح {a} الافتتاحية',
  '{a} has payments in Nasq360. Reverse them first.': '{a} عليه دفعات في Nasq360. اعكسها أولًا.',
  'The trial balance has no lines': 'ميزان المراجعة لا يحتوي على سطور',
  'Account 3900 is filled by Nasq360 itself: put the old system’s opening-balance line under capital or retained earnings': 'الحساب 3900 يملؤه Nasq360 بنفسه: ضع سطر الأرصدة الافتتاحية في النظام القديم تحت رأس المال أو الأرباح المحتجزة',
  'The trial balance doesn’t balance: debits {a}, credits {b}': 'ميزان المراجعة غير متوازن: المدين {a}، الدائن {b}',
  'entered the opening {a} ({b} lines)': 'أدخل {a} الافتتاحي ({b} سطر)',
  '{a}: enter the name or old system id': '{a}: أدخل الاسم أو المعرّف في النظام القديم',
  'Amount still owed: enter an amount': 'المبلغ المتبقي: أدخل مبلغًا',
  'The amount still owed can’t be more than the invoice total': 'لا يمكن أن يكون المبلغ المتبقي أكبر من إجمالي الفاتورة',
  'Opening documents are dated on or before {a}': 'المستندات الافتتاحية مؤرخة في {a} أو قبله',
  'The amount before VAT must be more than 0 and not more than the total': 'يجب أن يكون المبلغ قبل ضريبة القيمة المضافة أكبر من 0 ولا يزيد عن الإجمالي',
  'entered the opening {a} ({b} documents)': 'أدخل {a} الافتتاحية ({b} مستند)',
  'Direction: “{a}” is not one of the options': 'النوع: «{a}» ليس من الخيارات',
  'Amount: enter an amount': 'المبلغ: أدخل مبلغًا',
  'Only a received cheque can be under collection': 'الشيك الوارد فقط يمكن أن يكون تحت التحصيل',
  'entered the opening {a} ({b} cheques)': 'أدخل {a} الافتتاحية ({b} شيك)',
  'Items not yet on a statement are for bank accounts': 'البنود غير الظاهرة في الكشف خاصة بالحسابات البنكية',
  'This account was already reconciled after the opening date': 'تمت مطابقة هذا الحساب بالفعل بعد تاريخ الافتتاح',
  'entered the opening {a} ({b})': 'أدخل {a} الافتتاحي ({b})',
  'Add a Products module first': 'أضف وحدة المنتجات أولًا',
  'Product: enter the code or name': 'المنتج: أدخل الكود أو الاسم',
  '{a} is in the sheet twice': '{a} موجود في الملف مرتين',
  'entered the opening {a} ({b} products)': 'أدخل {a} الافتتاحي ({b} منتج)',
  'Going live on the first day of a quarter leaves no withholding tax from before it to bring in': 'بدء العمل في أول يوم من الربع لا يترك خصمًا من المنبع قبله لإدخاله',
  'Only withholding from {a} to {b} (this quarter, before going live) is brought in': 'يُدخل فقط الخصم من المنبع من {a} إلى {b} (هذا الربع، قبل بدء العمل)',
  'Amount before VAT: enter an amount': 'المبلغ قبل ضريبة القيمة المضافة: أدخل مبلغًا',
  'Only an admin can go live': 'المسؤول فقط يمكنه بدء العمل',
  'Bring in the trial balance first': 'أدخل ميزان المراجعة أولًا',
  'Opening balance equity (3900) must be zero to go live; it is {a}. What was brought in doesn’t add up to the trial balance yet.': 'يجب أن يكون حساب الأرصدة الافتتاحية (3900) صفرًا لبدء العمل؛ رصيده {a}. ما تم إدخاله لا يطابق ميزان المراجعة بعد.',
  '{a} accounts differ from the trial balance. Write why they are accepted (at least 10 characters).': '{a} حسابات تختلف عن ميزان المراجعة. اكتب سبب قبولها (10 أحرف على الأقل).',
  'went live on {a}: the opening balances are final and the books are closed up to {b}': 'بدأ العمل في {a}: الأرصدة الافتتاحية نهائية والدفاتر مقفلة حتى {b}',
  'Only an admin can reopen the opening balances': 'المسؤول فقط يمكنه إعادة فتح الأرصدة الافتتاحية',
  'The opening balances aren’t final yet': 'الأرصدة الافتتاحية ليست نهائية بعد',
  'Write why the opening balances are reopened (at least 10 characters)': 'اكتب سبب إعادة فتح الأرصدة الافتتاحية (10 أحرف على الأقل)',
  'Months were closed after going live. Reopen those books first.': 'تم إقفال شهور بعد بدء العمل. أعد فتح تلك الدفاتر أولًا.',
