  'The sheet needs a column for each month (January to December, or 1 to 12), or a “Year total” column': 'يلزم الملف عمود لكل شهر (من يناير إلى ديسمبر، أو من 1 إلى 12)، أو عمود «إجمالي السنة»',
  'The sheet needs an “Account” column with the account code': 'يلزم الملف عمود «الحساب» بكود الحساب',
  'The year’s income and expenses per account and month, and per cost center if you like. Start it from last year’s actuals, type it in, or bring it from Excel. It is submitted and approved by another admin; the approved version is what the books are measured against. Revise it during the year: the earlier version is kept.': 'إيرادات العام ومصروفاته لكل حساب وكل شهر، ولكل مركز تكلفة إن شئت. ابدأها من فعلي العام الماضي، أو اكتبها، أو أدخلها من إكسل. تُقدَّم ويعتمدها مسؤول آخر؛ والنسخة المعتمدة هي التي تُقاس بها الدفاتر. راجِعها خلال العام: تبقى النسخة السابقة محفوظة.',
