  'A year’s target per rep, product or customer (a group counts every customer under it), spread over the months like last year’s sales. Sales are before VAT, credit notes taken off; a rep’s sales are the invoices of the customers they own.': 'مستهدف العام لكل مندوب أو منتج أو عميل (وتُحسب للمجموعة مبيعات كل عميل تحتها)، موزّعًا على الشهور مثل مبيعات العام الماضي. المبيعات قبل الضريبة وبعد خصم إشعارات الدائن؛ ومبيعات المندوب هي فواتير العملاء المسؤول عنهم.',
