  'A plan for the next 3 to 5 years, built from your assumptions and started from your own books: sales per product line, cost of sales, staff, overheads, investments, loans and capital. Its profit and loss, balance sheet and cash flow always agree. Change an assumption and see the effect at once, in the base, best and worst case.': 'خطة للسنوات الثلاث إلى الخمس القادمة، مبنية على افتراضاتك وتبدأ من دفاترك: المبيعات لكل خط منتجات، وتكلفة المبيعات، والعاملون، والمصروفات العامة، والاستثمارات، والقروض، ورأس المال. قائمة الدخل والميزانية والتدفقات النقدية فيها متفقة دائمًا. غيّر أي افتراض وشاهد أثره فورًا في الحالة الأساسية وأفضل حالة وأسوأ حالة.',
