  'Tick the movements that appear on the bank statement (or load the bank’s CSV to tick them for you), and enter the statement’s ending balance. It must agree to the piastre.': 'علّم الحركات الظاهرة في كشف البنك (أو حمّل ملف CSV من البنك ليعلّمها لك)، وأدخل الرصيد الختامي للكشف. يجب أن يتطابق حتى القرش.',
