  'Register, answer a few questions, and get a working CRM + ERP you can reshape by dragging and dropping.': 'سجّل وأجب عن بضعة أسئلة، واحصل على نظام إدارة عملاء وتخطيط موارد جاهز تعيد تشكيله بالسحب والإفلات.',
  'Privacy': 'الخصوصية',
  'Data processing': 'معالجة البيانات',
  'Nile Valley – RO plant': 'وادي النيل – محطة تحلية',
  'Delta Foods – upgrade': 'دلتا للأغذية – تطوير',
