  'EGP 4.2M open': 'EGP 4.2 مليون مفتوحة',
  'Health check: 100%': 'فحص السلامة: 100%',
  'Task created: call new lead': 'أُنشئت مهمة: اتصل بالعميل المحتمل الجديد',
  'Quotation draft created for the deal': 'أُنشئت مسودة عرض سعر للصفقة',
  'Make a quotation': 'اعمل عرض سعر',
  'Trail': 'المسار',
  'Made from': 'أُنشئ من',
  'Led to': 'أدى إلى',
  'matched the existing customer “{a}” by phone': 'طابق العميل الموجود «{a}» برقم الهاتف',
  'Quotations are made from deals': 'عروض الأسعار تُعمل من الصفقات',
  'Add a Quotations module first': 'أضف قائمة عروض الأسعار أولاً',
  'Choose the deal’s customer first': 'اختر عميل الصفقة أولاً',
  'made a quotation for the deal “{a}”': 'عمل عرض سعر للصفقة «{a}»',
  'This change is not valid': 'هذا التغيير غير صالح',
  '{a} is already paid in full. A colleague may have just registered the payment.': '{a} مدفوعة بالكامل بالفعل. ربما سجّل أحد زملائك الدفعة للتو.',
  '{a} was voided, so it takes no payment': '{a} ملغاة، فلا تقبل أي دفعة',
  'Sample data.': 'بيانات تجريبية.',
  'Documents numbered SAMPLE- are examples. Remove them before your first real invoice.': 'المستندات المرقّمة بـ SAMPLE- أمثلة. احذفها قبل أول فاتورة حقيقية.',
  'Not now': 'ليس الآن',
  'Where this document is': 'مرحلة هذا المستند',
  'Save draft': 'حفظ كمسودة',
  'Sent': 'مُرسل',
  'Posted': 'مُرحّل',
  'Invoice made': 'صدرت الفاتورة',
  'Fill in the customer and the lines, then Save draft.': 'اختر العميل وأضف البنود، ثم اضغط «حفظ كمسودة».',
  'Next: when you send it to the customer, press Mark sent. That gives it its number.': 'الخطوة التالية: عند إرساله للعميل اضغط «تمييز كمُرسل»، فيأخذ رقمه.',
  'Next: when the customer answers, press Mark accepted or Declined. You can also Create invoice straight away.': 'الخطوة التالية: عند رد العميل اضغط «تمييز كمقبول» أو «مرفوض». ويمكنك أيضًا «إنشاء فاتورة» مباشرة.',
  'Next: press Create invoice. The invoice starts as a draft you can check before posting.': 'الخطوة التالية: اضغط «إنشاء فاتورة». تبدأ الفاتورة كمسودة تراجعها قبل الترحيل.',
  'Done: an invoice was made from this quotation (see the trail).': 'تم: صدرت فاتورة من عرض السعر هذا (انظر المسار).',
  'The customer declined it. Nothing more to do.': 'رفضه العميل. لا شيء آخر مطلوب.',
  'Fill in the details and the lines, then Save draft. Nothing reaches the books until it is posted.': 'املأ البيانات وأضف البنود، ثم اضغط «حفظ كمسودة». لا يدخل شيء في الدفاتر حتى يُرحّل.',
  'Next: check it, then press Post. Posting gives it its number, records the sale in the books and takes the goods out of stock. After that it can’t be edited, only credited or voided.': 'الخطوة التالية: راجعها ثم اضغط «ترحيل». الترحيل يعطيها رقمها ويسجل البيع في الدفاتر ويخصم البضاعة من المخزون. بعدها لا يمكن تعديلها، بل يُعمل لها إشعار دائن أو تُلغى.',
  'Next: check it against the supplier’s bill, then press Post. Posting records the cost in the books and adds the goods to stock. After that it can’t be edited, only debited or voided.': 'الخطوة التالية: طابقها مع فاتورة المورد ثم اضغط «ترحيل». الترحيل يسجل التكلفة في الدفاتر ويضيف البضاعة للمخزون. بعدها لا يمكن تعديلها، بل يُعمل لها إشعار مدين أو تُلغى.',
  'Next: someone who can post (finance or an admin) checks it and posts it.': 'الخطوة التالية: يراجعها ويرحّلها من له صلاحية الترحيل (المالية أو المدير).',
  'Overdue since {due}: {left} not yet received. Press Register payment when it arrives.': 'متأخرة منذ {due}: لم يُحصّل {left} بعد. اضغط «تسجيل دفعة» عند وصولها.',
  'Overdue since {due}: {left} not yet paid to the supplier. Press Register payment when you pay.': 'متأخرة منذ {due}: لم يُدفع {left} للمورد بعد. اضغط «تسجيل دفعة» عند الدفع.',
  'Next: when the customer pays, press Register payment. Due by {due}.': 'الخطوة التالية: عندما يدفع العميل اضغط «تسجيل دفعة». تستحق في {due}.',
  'Next: when you pay the supplier, press Register payment. Due by {due}.': 'الخطوة التالية: عندما تدفع للمورد اضغط «تسجيل دفعة». تستحق في {due}.',
  'Overdue since {due}: {left} still to receive. Press Register payment when it arrives.': 'متأخرة منذ {due}: باقٍ {left} للتحصيل. اضغط «تسجيل دفعة» عند وصولها.',
  'Overdue since {due}: {left} still to pay. Press Register payment when you pay.': 'متأخرة منذ {due}: باقٍ {left} للدفع. اضغط «تسجيل دفعة» عند الدفع.',
  '{left} still to receive by {due}. Press Register payment for each payment.': 'باقٍ {left} للتحصيل حتى {due}. اضغط «تسجيل دفعة» لكل دفعة.',
  '{left} still to pay by {due}. Press Register payment for each payment.': 'باقٍ {left} للدفع حتى {due}. اضغط «تسجيل دفعة» لكل دفعة.',
  'Done: paid in full. To take goods back or correct it, make a credit note (under ⋯).': 'تم: مسددة بالكامل. لاسترجاع بضاعة أو تصحيحها اعمل «إشعار دائن» (من ⋯).',
  'Done: paid in full. To return goods or correct it, make a debit note (under ⋯).': 'تم: مسددة بالكامل. لرد بضاعة أو تصحيحها اعمل «إشعار مدين» (من ⋯).',
  'Voided: its stock and journal entries were reversed. Nothing more to do.': 'ملغاة: عُكست حركات المخزون والقيود. لا شيء آخر مطلوب.',
  'Day to day': 'العمل اليومي',
  'Month end & setup': 'إقفال الشهر والإعداد',
  'Invoices, purchases, stock and the books: what is sold, bought, paid and owed.': 'الفواتير والمشتريات والمخزون والدفاتر: ما يُباع ويُشترى ويُدفع ويُستحق.',
  'Customer relations': 'علاقات العملاء',
  'Leads, customers, deals and quotations: from the first contact to the order.': 'العملاء المحتملون والعملاء والصفقات وعروض الأسعار: من أول تواصل حتى الطلب.',
  'Planning': 'التخطيط',
  'The business plan, budgets and sales targets: where the company is heading.': 'خطة العمل والموازنات وأهداف المبيعات: إلى أين تتجه الشركة.',
