  'Bring your data in, your team, billing, the audit trail and how the system works.': 'إدخال بياناتك، فريقك، الاشتراك، سجل التدقيق، وطريقة عمل النظام.',
  'Sales analysis & targets': 'تحليل المبيعات والأهداف',
