  'Where do you want to work today?': 'أين تريد أن تعمل اليوم؟',
  'Selling': 'البيع',
  'Each invoice: Draft → Posted → Paid. Register payments on the invoice; the books update by themselves.': 'كل فاتورة: مسودة ← مُرحّلة ← مسددة. سجّل الدفعات على الفاتورة، والدفاتر تتحدث وحدها.',
  'Accepted quotations from Customer relations arrive here as invoice drafts.': 'عروض الأسعار المقبولة من علاقات العملاء تصل هنا كمسودات فواتير.',
  'Buying': 'الشراء',
  'Post the supplier’s bill when it arrives: stock and what you owe update; pay it from the bill.': 'رحّل فاتورة المورد عند وصولها: يتحدث المخزون وما عليك، وادفعها من الفاتورة نفسها.',
  'The books': 'الدفاتر',
  'From the first contact to the order': 'من أول تواصل حتى الطلب',
  'A lead becomes a customer and a deal; an accepted quotation becomes an invoice draft in Operations.': 'العميل المحتمل يصبح عميلًا وصفقة، وعرض السعر المقبول يصبح مسودة فاتورة في العمليات.',
  'A lead becomes a customer and a deal; the deal’s quotation closes it.': 'العميل المحتمل يصبح عميلًا وصفقة، وعرض سعر الصفقة يغلقها.',
