  'Also here': 'وأيضًا هنا',
  'From the long view to this month': 'من النظرة البعيدة إلى هذا الشهر',
  'The business plan sets the direction for 3–5 years, the budget turns it into this year’s figures, and the sales analysis tracks the year against its targets.': 'خطة العمل تحدد الاتجاه لـ 3–5 سنوات، والموازنة تحوّلها إلى أرقام هذا العام، وتحليل المبيعات يتابع العام مقابل أهدافه.',
  'Getting set up': 'البدء والإعداد',
  'Bring your data in first, then invite the team; change lists and fields at any time.': 'أدخل بياناتك أولًا ثم ادعُ الفريق، ويمكنك تعديل القوائم والحقول في أي وقت.',
