  'Used in both: Customer relations and Operations': 'مستخدمة في الاثنين: علاقات العملاء والعمليات',
  'Choose what each role can see and do. A change applies at once to everyone with that role.': 'اختر ما يراه كل دور وما يفعله. أي تغيير يسري فورًا على كل من له هذا الدور.',
  'Team: who has which role': 'الفريق: من له أي دور',
