  'Role name': 'اسم الدور',
  'Move its people to another role first (on the Team page)': 'انقل أصحاب هذا الدور إلى دور آخر أولًا (من صفحة الفريق)',
  'Remove role': 'حذف الدور',
  'This role works in': 'يعمل هذا الدور في',
  'No area yet: give it rights below': 'لا يوجد قسم بعد: امنحه صلاحيات بالأسفل',
  'An area opens when the role can add or change records in a list of that area. Looking only does not open it.': 'يظهر القسم عندما يستطيع الدور إضافة أو تعديل سجلات في قائمة من قوائمه. العرض فقط لا يُظهره.',
  'The Admin role has full access to everything, always: every list, the books, the team and the setup. Give it only to people you trust with the whole company.': 'دور المسؤول له صلاحية كاملة دائمًا على كل شيء: كل القوائم والدفاتر والفريق والإعداد. امنحه فقط لمن تأتمنه على الشركة كلها.',
  'Post invoices and bills, void them, register payments, see the books and the accounting.': 'ترحيل الفواتير وفواتير الموردين وإلغاؤها وتسجيل الدفعات، والاطلاع على الدفاتر والحسابات.',
  'Purchase costs, stock value and margins. Finance roles always see them.': 'تكاليف الشراء وقيمة المخزون والهوامش. أدوار المالية تراها دائمًا.',
  'All lists in {group}': 'كل القوائم في {group}',
  'People with this role': 'أصحاب هذا الدور',
  'Nobody yet. Give someone this role on the Team page.': 'لا أحد بعد. امنح أحدًا هذا الدور من صفحة الفريق.',
  'Unsaved changes to “{name}”': 'تغييرات غير محفوظة على «{name}»',
