  'Add the role': 'إضافة الدور',
  'What each role can see and do': 'ما يراه كل دور وما يفعله',
  'Bring your data in first, invite the team, then choose what each role can see and do; change lists and fields at any time.': 'أدخل بياناتك أولًا، ثم ادعُ الفريق، ثم اختر ما يراه كل دور وما يفعله؛ ويمكنك تعديل القوائم والحقول في أي وقت.',
  'Give the role a name': 'أعطِ الدور اسمًا',
  'There is already a role called “{a}”': 'يوجد بالفعل دور باسم «{a}»',
  'The Admin role always has full access': 'دور المسؤول له صلاحية كاملة دائمًا',
  'Up to 30 roles': 'حتى 30 دورًا',
  'The Admin role can’t be removed': 'لا يمكن حذف دور المسؤول',
  'Move the people who have this role ({a}) to another role first (on the Team page)': 'انقل أصحاب هذا الدور ({a}) إلى دور آخر أولًا (من صفحة الفريق)',
  'An approval rule is decided by this role: choose another approver first': 'هذا الدور يعتمد قاعدة موافقة: اختر معتمدًا آخر أولًا',
