  'Tip: the owner and admins can also arrange access in the app, at Setup → Access rights. Changes there apply at once, without publishing.': 'نصيحة: يمكن للمالك والمديرين أيضًا ترتيب الصلاحيات من داخل التطبيق: الإعداد ← صلاحيات الوصول. التغييرات هناك تسري فورًا دون نشر.',
