  'Start empty': 'ابدأ فارغًا',
  'Start from an example': 'ابدأ من مثال',
  'Tables from several lists, downloaded as Excel': 'جداول من عدة قوائم، تُنزَّل كملف إكسل',
  'Tables with columns from different lists, downloaded as Excel. Everyone finds them on the Excel reports page.': 'جداول بأعمدة من قوائم مختلفة، تُنزَّل كملف إكسل. يجدها الجميع في صفحة تقارير إكسل.',
  'Tables with columns from several lists (customer, product, date, invoice number…), downloaded as Excel.': 'جداول بأعمدة من عدة قوائم (العميل، المنتج، التاريخ، رقم الفاتورة…)، تُنزَّل كملف إكسل.',
  'Tables with columns from several lists, ready to download as Excel. You see only the lists your role can open.': 'جداول بأعمدة من عدة قوائم، جاهزة للتنزيل كملف إكسل. ترى فقط القوائم التي يسمح بها دورك.',
  'The owner or an admin designs these reports; once they publish one you can open it, it appears here.': 'يصمّم المالك أو المدير هذه التقارير؛ وحين ينشر تقريرًا يمكنك فتحه، يظهر هنا.',
  'VAT %': 'الضريبة ٪',
  'Your role can’t open the list behind these columns, so they are left empty: {a}': 'دورك لا يسمح بفتح القائمة التي تأتي منها هذه الأعمدة، لذلك تُركت فارغة: {a}',
  'from': 'من',
  'one row per product sold': 'صف لكل منتج مباع',
