  'A column of “{a}” points to a field that no longer exists': 'عمود في «{a}» يشير إلى حقل لم يعد موجودًا',
  'A chart uses a column that is no longer in the report': 'رسم بياني يستخدم عمودًا لم يعد في التقرير',
  'A report can have up to 40 columns': 'يمكن أن يضم التقرير حتى 40 عمودًا',
  'Add a chart': 'أضف رسمًا بيانيًا',
  'Add at least one column': 'أضف عمودًا واحدًا على الأقل',
  'Add columns from any linked list': 'أضف أعمدة من أي قائمة مرتبطة',
  'Average of {a}': 'متوسط {a}',
  'Build one from several lists: for example the customer’s name, the product sold, the date of the sale and the invoice number, with the totals and a chart of sales by product.': 'أنشئ تقريرًا من عدة قوائم: مثلًا اسم العميل، والمنتج المباع، وتاريخ البيع، ورقم الفاتورة، مع الإجماليات ورسم بياني للمبيعات حسب المنتج.',
  'Charts show on the page and go into the Excel file as real Excel charts (a “Charts” sheet).': 'تظهر الرسوم في الصفحة وتُضاف إلى ملف الإكسل كرسوم إكسل حقيقية (في ورقة «الرسوم البيانية»).',
  'Charts': 'الرسوم البيانية',
