  'Number of rows': 'عدد الصفوف',
  'Number of {a}': 'عدد {a}',
  'Open the Excel reports page': 'افتح صفحة تقارير إكسل',
  'Remove chart': 'إزالة الرسم',
  'Report deleted': 'تم حذف التقرير',
  'Report saved: everyone who may open it sees it now': 'تم حفظ التقرير: يراه الآن كل من يُسمح له بفتحه',
  'Report saved: it goes live with the next publish, as it uses fields not published yet': 'تم حفظ التقرير: سيظهر مع النشر القادم لأنه يستخدم حقولًا لم تُنشر بعد',
  'Save report': 'حفظ التقرير',
  'Saving applies at once: everyone whose role can open the list sees the report on the Excel reports page.': 'الحفظ يُطبَّق فورًا: يرى التقرير في صفحة تقارير إكسل كل من يسمح له دوره بفتح القائمة.',
  'Search every list’s fields': 'ابحث في حقول كل القوائم',
  'Set up the system first': 'أعدّ النظام أولًا',
  'Sum of {a}': 'مجموع {a}',
  'Tables with columns from several lists, with totals and charts, downloaded as Excel. They save at once and need no publishing.': 'جداول بأعمدة من عدة قوائم، مع الإجماليات والرسوم، تُنزَّل كملف إكسل. تُحفظ فورًا ولا تحتاج إلى نشر.',
  'Tables with columns from several lists, with totals and charts, ready to download as Excel. You see only the lists your role can open.': 'جداول بأعمدة من عدة قوائم، مع الإجماليات والرسوم، جاهزة للتنزيل كملف إكسل. ترى فقط القوائم التي يسمح بها دورك.',
  'That report is not valid': 'هذا التقرير غير صالح',
  'That report no longer exists': 'هذا التقرير لم يعد موجودًا',
  'The owner or an admin designs these reports; once they save one you can open, it appears here.': 'يصمّم المالك أو المدير هذه التقارير؛ وحين يحفظ تقريرًا يمكنك فتحه، يظهر هنا.',
  'The product on the line': 'منتج البند',
  'This {a}': 'هذا السجل: {a}',
