  '1 chart': 'رسم واحد',
  'Each chart here uses one list. For a report with columns from several lists (the customer’s name, the product sold, the date, the invoice number…), with totals and charts, use Excel sheets.': 'كل رسم هنا يستخدم قائمة واحدة. لتقرير بأعمدة من عدة قوائم (اسم العميل، المنتج المباع، التاريخ، رقم الفاتورة…) مع الإجماليات والرسوم، استخدم جداول إكسل.',
  'Open Excel sheets': 'افتح جداول إكسل',
  'Data from (one list)': 'البيانات من (قائمة واحدة)',
  'Add up': 'اجمعها',
  'Combine': 'طريقة الدمج',
  'Each row has several of these: a column adds them up, takes the latest, counts or lists them (you can change how in step 3). Drafts, voided and declined documents are left out.': 'لكل صف عدة سجلات من هذه: العمود يجمعها أو يأخذ أحدثها أو يعدّها أو يسردها (يمكنك تغيير ذلك في الخطوة 3). لا تُحسب المسودات والمستندات الملغاة والمرفوضة.',
  'Highest / latest': 'الأعلى / الأحدث',
  'How many': 'العدد',
  'Its lines': 'بنودها',
  'Lines of {a}': 'بنود {a}',
  'List them': 'اسردها',
  'Lowest / earliest': 'الأقل / الأقدم',
  'One for each row': 'واحد لكل صف',
  'Several for each row (counted, added up or listed)': 'عدة لكل صف (تُعدّ أو تُجمع أو تُسرد)',
