  '2. Spread': '2. التوزيع',
  '3. What changes': '3. ما الذي سيتغير',
  'A bill can’t take its own costs: choose the bills of the goods': 'لا تأخذ الفاتورة تكاليفها هي: اختر فواتير البضاعة',
  'Add to the cost of goods': 'أضف إلى تكلفة البضاعة',
