  'Worth doing': 'يستحق الفعل',
  'The AI could not write this plan. The check-up results above still stand.': 'لم يستطع الذكاء الاصطناعي كتابة هذه الخطة. نتائج الفحص أعلاه ما زالت صحيحة.',
  'The AI is busy. Try again in a minute.': 'الذكاء الاصطناعي مشغول. حاول بعد دقيقة.',
  'The AI key in the server settings is not valid. An admin needs to replace it.': 'مفتاح الذكاء الاصطناعي في إعدادات الخادم غير صالح. يلزم أن يستبدله المسؤول.',
  'The AI could not answer just now. Try again in a moment.': 'لم يستطع الذكاء الاصطناعي الرد الآن. حاول بعد لحظات.',
