  'Invoices take the batch that expires first, and never an expired one. Batches come in on purchase bills (Batch no. and Expiry on each line).': 'تأخذ الفواتير التشغيلة الأقرب انتهاءً أولًا، ولا تأخذ أبدًا تشغيلة منتهية. تدخل التشغيلات مع فواتير الشراء (رقم التشغيلة والصلاحية في كل بند).',
