  'Only {a} of {b} can be sold: {c} are in expired batches. Write the expired batches off first.': 'يمكن بيع {a} فقط من {b}: يوجد {c} في تشغيلات منتهية الصلاحية. أعدم التشغيلات المنتهية أولًا.',
