  'Reverse automatically on (accruals)': 'يُعكس تلقائيًا في (للمستحقات)',
  'An opposite entry is posted on {date}, so when the real bill arrives it is entered as usual and the expense isn’t counted twice.': 'يُرحَّل قيد عكسي في {date}، فعند وصول الفاتورة الفعلية تُسجَّل كالمعتاد ولا يُحسب المصروف مرتين.',
