  'Book value': 'القيمة الدفترية',
  'Straight line, a full month from the month an asset goes into service, down to its salvage value. One entry for all assets, dated the month’s last day: debit 5600 Depreciation, credit 1590 Accumulated depreciation. Months not yet run are caught up.': 'قسط ثابت، شهر كامل من شهر بدء استخدام الأصل، حتى قيمته التخريدية. قيد واحد لكل الأصول بتاريخ آخر يوم في الشهر: من ح/ 5600 مصروف الإهلاك إلى ح/ 1590 مجمع الإهلاك. الشهور التي لم يُحتسب إهلاكها تُستكمل.',
