  'Bought with a supplier bill already charged to an expense? Choose that expense account here to move it into fixed assets.': 'اشتريته بفاتورة مورد حُمّلت على مصروف؟ اختر حساب ذلك المصروف هنا لنقله إلى الأصول الثابتة.',
