  'A cash difference needs the account 5510 Cash over and short in the chart of accounts': 'فرق النقدية يحتاج الحساب 5510 عجز وزيادة النقدية في دليل الحسابات',
  'closed {a} ({b}): counted {c}, expected {d}{e}': 'أغلق {a} ({b}): المعدود {c}، المتوقع {d}{e}',
  'Change to give': 'الباقي',
  'Connections': 'الربط مع الأنظمة',
  'Only admins can manage connections.': 'المسؤولون فقط يديرون الربط مع الأنظمة.',
  'Connect your web shop, bank, courier or reporting tool: they read and write through the API with a key, and webhooks tell them as soon as something happens.': 'اربط متجرك الإلكتروني أو البنك أو شركة الشحن أو أداة التقارير: تقرأ وتكتب عبر الواجهة البرمجية بمفتاح، وتُبلغها الإشعارات الفورية (Webhooks) فور حدوث أي شيء.',
  'API keys': 'مفاتيح الواجهة البرمجية (API)',
  'A key acts as you, with your rights, and every change it makes is in the audit trail under its name. Give each system its own key, read-only unless it must write.': 'المفتاح يعمل باسمك وبصلاحياتك، وكل تغيير يقوم به يُسجَّل في سجل المراجعة باسمه. أعطِ كل نظام مفتاحًا خاصًا، للقراءة فقط ما لم يحتج للكتابة.',
  'Your new key: copy it now, it won’t be shown again': 'مفتاحك الجديد: انسخه الآن، فلن يظهر مرة أخرى',
  'I saved it': 'حفظته',
  'e.g. Web shop': 'مثال: المتجر الإلكتروني',
  'It may': 'الصلاحية',
  'Read only': 'قراءة فقط',
  'Read and write': 'قراءة وكتابة',
  'Make a key': 'إنشاء مفتاح',
  'Key': 'المفتاح',
  'Acts as': 'يعمل باسم',
  'Last used': 'آخر استخدام',
  'Revoke the key “{a}”? The system using it stops working at once.': 'إلغاء المفتاح «{a}»؟ سيتوقف النظام الذي يستخدمه فورًا.',
  'Revoke': 'إلغاء',
  'Webhooks': 'الإشعارات الفورية (Webhooks)',
  'We send a signed message to your address as soon as something happens. If it doesn’t answer, we try again for a day.': 'نرسل رسالة موقّعة إلى عنوانك فور حدوث أي شيء. وإذا لم يرد نعيد المحاولة لمدة يوم.',
  'The signing secret: copy it now, it won’t be shown again': 'سر التوقيع: انسخه الآن، فلن يظهر مرة أخرى',
  'Address (https)': 'العنوان (https)',
  'Tell it when': 'أبلغه عندما',
  'Use a public https address.': 'استخدم عنوان https عامًا.',
  'Add the webhook': 'إضافة الإشعار',
  'Address': 'العنوان',
  'Events': 'الأحداث',
  'Last answer': 'آخر رد',
  'off: it kept failing': 'متوقف: تكرر فشله',
  'Remove this webhook?': 'حذف هذا الإشعار؟',
  'Latest deliveries': 'آخر الإرسالات',
  'Event': 'الحدث',
  'Given up': 'توقفت المحاولات',
  'Trying again': 'إعادة المحاولة',
  'How to use the API': 'طريقة استخدام الواجهة البرمجية',
  'Address: {a}. Lists: customers, suppliers, products, invoices, bills, quotes, deals, contacts, leads, tasks, and stock. GET a list or one record; POST to add (an invoice or bill can be posted with "post": true); PATCH to change; POST …/invoices/<id>/payments to record a payment.': 'العنوان: {a}. القوائم: customers وsuppliers وproducts وinvoices وbills وquotes وdeals وcontacts وleads وtasks وstock. استخدم GET لقائمة أو سجل، وPOST للإضافة (ويمكن ترحيل الفاتورة مع "post": true)، وPATCH للتعديل، وPOST …/invoices/<id>/payments لتسجيل دفعة.',
  'Each webhook message carries the header Nasq360-Signature: t=<time>,v1=<HMAC-SHA256 of "<time>.<body>" with your secret>. Check it, and that the time is within 5 minutes, before trusting the message.': 'كل رسالة تحمل الترويسة Nasq360-Signature: t=<الوقت>,v1=<HMAC-SHA256 لـ "<الوقت>.<المحتوى>" بسرّك>. تحقق منها ومن أن الوقت خلال 5 دقائق قبل الوثوق بالرسالة.',
  'API keys and webhooks for your shop, bank, courier or reports': 'مفاتيح API والإشعارات الفورية لمتجرك أو البنك أو الشحن أو التقارير',
  'A customer is added': 'إضافة عميل',
  'A customer is changed': 'تعديل عميل',
  'A supplier is added': 'إضافة مورد',
