  'Buy next': 'ما يجب شراؤه',
  'At or under the reorder level, counting what is held for sales orders and what is already on order. The quantity brings it back to the level plus a month of sales (or the product’s reorder quantity), in whole cartons.': 'عند حد إعادة الطلب أو أقل، مع حساب المحجوز لأوامر البيع وما هو مطلوب بالفعل. الكمية تعيده إلى الحد مضافًا إليه مبيعات شهر (أو كمية إعادة الطلب للصنف)، بكراتين كاملة.',
  'No supplier yet': 'لا يوجد مورد بعد',
