  'Scan with the camera': 'المسح بالكاميرا',
  'Scan': 'مسح',
  'The camera wasn’t allowed. Allow it in the browser, or type the code below.': 'لم يُسمح بالكاميرا. اسمح بها في المتصفح، أو اكتب الكود بالأسفل.',
  'No camera can be used here. Type the code below, or use a USB scanner.': 'لا توجد كاميرا متاحة هنا. اكتب الكود بالأسفل أو استخدم قارئ باركود USB.',
  'Scan a barcode': 'مسح باركود',
  'Read: {c}. Keep scanning, or close when done.': 'تمت قراءة: {c}. واصل المسح أو أغلق عند الانتهاء.',
  'Read: {c}': 'تمت قراءة: {c}',
