  'Barcodes': 'الباركود',
  'Add a barcode': 'إضافة باركود',
  'Scan it at the counter, on invoices and in counts. Its code ({c}) works too.': 'امسحه على الكاشير وفي الفواتير وفي الجرد. كوده ({c}) يعمل أيضًا.',
