  'Connected: {p}. Customers’ messages arrive in the WhatsApp inbox.': 'متصل: {p}. تصل رسائل العملاء إلى صندوق واتساب.',
  'In Meta for Developers → your app → WhatsApp → Configuration, set:': 'في Meta for Developers ← تطبيقك ← WhatsApp ← Configuration، اضبط:',
  'Callback URL': 'رابط الاستدعاء (Callback URL)',
