  'Change the number or token': 'تغيير الرقم أو الرمز',
  'Disconnect WhatsApp? Messages already received stay.': 'فصل واتساب؟ تبقى الرسائل المستلمة كما هي.',
  'Disconnect': 'فصل',
  'Answer customers’ WhatsApp messages from here, linked to each customer, and send quotations and invoices on WhatsApp. It uses your own WhatsApp Business number through Meta (WhatsApp Cloud API).': 'رد على رسائل واتساب من العملاء من هنا، مرتبطة بكل عميل، وأرسل عروض الأسعار والفواتير على واتساب. يستخدم رقم واتساب للأعمال الخاص بك عبر Meta (WhatsApp Cloud API).',
  'WhatsApp messages come with the Pro plan (Billing page).': 'رسائل واتساب متاحة في الباقة الاحترافية (صفحة الفوترة).',
  'Connect WhatsApp': 'ربط واتساب',
  'From Meta for Developers → your app → WhatsApp → API Setup: the phone number ID and a permanent access token (a system user’s); from App settings → Basic: the app secret. They are kept on the server and never shown again.': 'من Meta for Developers ← تطبيقك ← WhatsApp ← API Setup: معرّف رقم الهاتف ورمز وصول دائم (لمستخدم نظام)، ومن App settings ← Basic: سر التطبيق. تُحفظ على الخادم ولا تظهر مرة أخرى.',
  'Phone number ID': 'معرّف رقم الهاتف',
  'The number customers see': 'الرقم الذي يراه العملاء',
  'Access token': 'رمز الوصول',
  'App secret': 'سر التطبيق',
  'Connect': 'ربط',
  'Customers’ WhatsApp messages, answered by the team': 'رسائل واتساب من العملاء يرد عليها الفريق',
  'WhatsApp isn’t connected yet: an admin connects it in Setup → Connections.': 'واتساب غير مربوط بعد: يربطه المسؤول من الإعداد ← الربط مع الأنظمة.',
  'No messages yet. Customers who write to {p} appear here.': 'لا توجد رسائل بعد. يظهر هنا العملاء الذين يراسلون {p}.',
