  'Write a reply…': 'اكتب ردًا…',
  'Send': 'إرسال',
  'The customer last wrote more than 24 hours ago, so WhatsApp allows only a template you made in WhatsApp Manager.': 'آخر رسالة من العميل منذ أكثر من 24 ساعة، لذا يسمح واتساب فقط بقالب أعددته في WhatsApp Manager.',
  'Template name': 'اسم القالب',
  'Language': 'اللغة',
