  'They haven’t written in the last 24 hours, so WhatsApp allows only a template you made in WhatsApp Manager (for example one with the number, the total and the link).': 'لم يراسلوك خلال آخر 24 ساعة، لذا يسمح واتساب فقط بقالب أعددته في WhatsApp Manager (مثلًا قالب فيه الرقم والإجمالي والرابط).',
  'Not verified': 'لم يتم التحقق',
