  'WhatsApp isn’t connected yet: an admin connects it in Setup → Connections': 'واتساب غير مربوط بعد: يربطه المسؤول من الإعداد ← الربط مع الأنظمة',
  'That isn’t a phone number WhatsApp can reach': 'هذا ليس رقم هاتف يصل إليه واتساب',
  'Write the template’s name as it is in WhatsApp Manager': 'اكتب اسم القالب كما هو في WhatsApp Manager',
  'Write the message': 'اكتب الرسالة',
  'The customer hasn’t written in the last 24 hours: WhatsApp allows only an approved template now': 'لم يراسلك العميل خلال آخر 24 ساعة: يسمح واتساب الآن بقالب معتمد فقط',
  'WhatsApp refused it: {a}': 'رفضها واتساب: {a}',
  'WhatsApp messages come with the Pro plan (Billing page)': 'رسائل واتساب متاحة في الباقة الاحترافية (صفحة الفوترة)',
  'Your role can’t use the WhatsApp inbox': 'دورك لا يسمح باستخدام صندوق واتساب',
  'Sales between the group’s companies ({a}) are taken out of revenue and of the costs where the buyer booked them: what is left is sold outside the group.': 'المبيعات بين شركات المجموعة ({a}) مستبعدة من الإيرادات ومن التكاليف التي سجلها المشتري: الباقي هو ما بيع خارج المجموعة.',
  '{a} of profit on goods one company still holds from another is taken out of stock and profit, until they are sold outside the group.': '{a} من الربح على بضاعة لا تزال لدى شركة اشترتها من شركة أخرى في المجموعة مستبعدة من المخزون والربح حتى تُباع خارج المجموعة.',
  'Sales between group companies': 'مبيعات بين شركات المجموعة',
  'Bought from group companies': 'مشتريات من شركات المجموعة',
  'Profit not yet earned by the group (in its stock)': 'ربح لم تحققه المجموعة بعد (في مخزونها)',
  'Profit still in group stock': 'ربح لا يزال في مخزون المجموعة',
  'Cash forecast': 'توقع النقدية',
  'I can answer questions like the ones below. For anything else, an admin can switch on the AI.': 'أستطيع الإجابة عن أسئلة مثل التي بالأسفل. ولغير ذلك يمكن للمسؤول تفعيل الذكاء الاصطناعي.',
  'I didn’t understand that. Try one of the questions below.': 'لم أفهم السؤال. جرّب أحد الأسئلة بالأسفل.',
  'Ask about your business': 'اسأل عن شركتك',
  'Ask about your business… e.g. this month vs last': 'اسأل عن شركتك… مثلًا: الشهر ده مقارنة بالشهر اللي فات',
  'Thinking…': 'جارٍ التفكير…',
  'Ask': 'اسأل',
  'Answered by the AI from your figures. Check important numbers in the reports.': 'أجاب الذكاء الاصطناعي من أرقامك. راجع الأرقام المهمة في التقارير.',
  'Ask something else': 'اسأل عن شيء آخر',
  'Cash in the next 13 weeks': 'النقدية في الأسابيع الـ13 القادمة',
  'Cash and bank now: {a}': 'النقدية والبنوك الآن: {a}',
  'Week': 'الأسبوع',
  'Counter & cheques': 'الكاشير والشيكات',
  'Rent, salaries & spending': 'الإيجار والرواتب والمصروفات',
  'Customers: what they owe, on the day each one usually pays (its own record of paying late). Suppliers: bills on their due dates. Counter: the average weekly sales paid at once, from the last 12 weeks. Spending: what was paid straight from cash or bank each week, on average, plus the recurring entries on their dates. VAT: each month’s at the end of the next. Overdue amounts fall in the first weeks.': 'العملاء: ما عليهم، في اليوم الذي يدفع فيه كل عميل عادةً (حسب تأخره المعتاد). الموردون: الفواتير في تواريخ استحقاقها. الكاشير: متوسط المبيعات النقدية الأسبوعية من آخر 12 أسبوعًا. المصروفات: متوسط ما دُفع أسبوعيًا من النقدية أو البنك مباشرة، مع القيود المتكررة في مواعيدها. الضريبة: ضريبة كل شهر في نهاية الشهر التالي. المبالغ المتأخرة تقع في الأسابيع الأولى.',
  'Runs short in the week of {d}: {a}': 'تنقص النقدية في أسبوع {d}: {a}',
  'Lowest point: {a} (week of {d})': 'أقل رصيد: {a} (أسبوع {d})',
  'See the 13 weeks': 'عرض الـ13 أسبوعًا',
  '{n} done; not done: {f}': 'تم {n}؛ لم يتم: {f}',
  'Prepared: {n} steps posted': 'تم التجهيز: رُحّلت {n} خطوات',
  'Prepare everything ({n})': 'جهّز كل شيء ({n})',
  'Accrued, reversing on the 1st of next month': 'تم الاستحقاق، ويُعكس في أول الشهر القادم',
  'Accrue it': 'سجّل الاستحقاق',
  'Each prepared entry can still be seen in the journal, and undone where the app allows it, until the month is closed.': 'كل قيد مُجهّز يظهر في اليومية، ويمكن التراجع عنه حيث يسمح البرنامج، حتى يُقفل الشهر.',
  'Ask a question': 'اكتب سؤالًا',
  'Too much to send': 'البيانات أكبر من أن تُرسل',
  'The AI isn’t switched on yet: an admin adds the Anthropic key to the server settings.': 'الذكاء الاصطناعي غير مفعّل بعد: يضيف المسؤول مفتاح Anthropic إلى إعدادات الخادم.',
  'That is a lot of questions for one hour. Try again a little later.': 'أسئلة كثيرة خلال ساعة واحدة. حاول مرة أخرى بعد قليل.',
  'Post the {n} recurring entries and monthly shares due': 'ترحيل {n} من القيود المتكررة والأقساط الشهرية المستحقة',
  'Recurring entries and monthly shares are up to date': 'القيود المتكررة والأقساط الشهرية محدّثة',
  'Depreciate the fixed assets up to {m}': 'إهلاك الأصول الثابتة حتى {m}',
  'Depreciation is up to date': 'الإهلاك محدّث',
  'Set aside for customers who may not pay: {a} more': 'تجنيب مبلغ للعملاء الذين قد لا يدفعون: {a} إضافية',
  'The allowance for late customers is enough': 'مخصص العملاء المتأخرين كافٍ',
  'Restate {n} amounts owed in {c} at the latest rates': 'إعادة تقييم {n} من المبالغ المستحقة بـ {c} بآخر الأسعار',
  'Enter the closing rate of {c} to restate {n} amounts owed': 'أدخل سعر الإقفال لـ {c} لإعادة تقييم {n} من المبالغ المستحقة',
  '{s} bills every month but not yet for {m}: accrue about {a}': '{s} يرسل فاتورة كل شهر لكن ليس بعد عن {m}: سجّل استحقاقًا بحوالي {a}',
