  'Branches, departments and projects': 'الفروع والأقسام والمشروعات',
  'Profit and budgets can then be seen for each one, not only for the company as a whole.': 'يمكن عندها رؤية الربح والموازنات لكل منها، لا للشركة ككل فقط.',
  '{n} cost centers': '{n} مراكز تكلفة',
  'What needs a second person’s approval': 'ما يحتاج موافقة شخص ثانٍ',
  'Large invoices, purchases and journal entries wait for another person before they count.': 'الفواتير والمشتريات والقيود الكبيرة تنتظر شخصًا آخر قبل أن تُحتسب.',
  '{n} approval rules; journal vouchers {jv}': '{n} قواعد موافقة؛ قيود اليومية {jv}',
