  'Dollar invoices, bills and bank accounts keep their own currency, and are restated at each month end.': 'فواتير البيع والشراء والحسابات البنكية بالدولار تحتفظ بعملتها، وتُعاد قيمتها في نهاية كل شهر.',
  'Accounts kept in {c}': 'حسابات بعملة {c}',
  'Only {cur}': '{cur} فقط',
  'Only the people given the payroll right see salaries; the books show one total a month.': 'لا يرى الرواتب إلا من لديه صلاحية الرواتب؛ والدفاتر تُظهر إجماليًا واحدًا شهريًا.',
  '{n} roles with the payroll right': '{n} أدوار لها صلاحية الرواتب',
  'Opening balances from the old system': 'الأرصدة الافتتاحية من النظام القديم',
  'The first day’s balances must agree with the old books before anything new is entered.': 'يجب أن تتطابق أرصدة اليوم الأول مع الدفاتر القديمة قبل إدخال أي جديد.',
  'Went live on {d}': 'بدأ التشغيل في {d}',
  'Not brought in yet': 'لم تُدخل بعد',
  'Customers and products': 'العملاء والأصناف',
  'Bring them in from Excel once, checked row by row before anything is saved.': 'أدخلها من Excel مرة واحدة، مع فحص كل سطر قبل حفظ أي شيء.',
  '{a} customers, {p} products': '{a} عملاء، {p} أصناف',
  'Setup session': 'جلسة الإعداد',
