  'A row was refused while saving, so nothing was imported (the parts already saved were taken back). Fix the rows below and import again.': 'رُفض صف أثناء الحفظ، فلم يُستورد شيء (وتم التراجع عن الأجزاء المحفوظة). صحّح الصفوف أدناه ثم استورد مرة أخرى.',
