  'A company’s owner or admin asks, with the reason. Open it for the days the change needs, or until you close it.': 'يطلب مالك الشركة أو مديرها مع ذكر السبب. افتحه للأيام التي يحتاجها التعديل، أو حتى تغلقه.',
