  'Customise': 'التخصيص',
  'Only the owner or an admin can customise.': 'المالك أو مدير النظام فقط يمكنه التخصيص.',
  'Add, arrange and resize the charts on the dashboard, and build Excel reports. Changes show at once for everyone.': 'أضف الرسوم البيانية في لوحة التحكم ورتّبها وغيّر حجمها، وأنشئ تقارير Excel. تظهر التغييرات فورًا للجميع.',
  'The colour and icon of each list. Light or dark is chosen with the screen button at the top.': 'لون وأيقونة كل قائمة. يُختار الوضع الفاتح أو الداكن من زر الشاشة في الأعلى.',
  'Customise the system': 'تخصيص النظام',
  'Lists, fields, pipelines, automations, rules and roles decide how the company works. To keep them from changing by accident, Nasq360 opens them when the owner or an admin asks, for the time the change needs.': 'القوائم والحقول والمراحل والأتمتة والقواعد والأدوار تحدد طريقة عمل الشركة. ولكي لا تتغير عن طريق الخطأ، يفتحها فريق Nasq360 عند طلب المالك أو مدير النظام، للمدة التي يحتاجها التعديل.',
  'Nasq360 team: always open for you.': 'فريق Nasq360: مفتوح لك دائمًا.',
  'Open until {date}.': 'مفتوح حتى {date}.',
  'Open until Nasq360 closes it again.': 'مفتوح حتى يغلقه فريق Nasq360.',
