  'Customising the system is closed for this company. Ask Nasq360 to open it (Setup → Customise system).': 'تخصيص النظام مغلق لهذه الشركة. اطلب من Nasq360 فتحه (الإعداد ← التخصيص ← تخصيص النظام).',
  'Couldn’t check whether customising is open. Try again in a moment.': 'تعذر التحقق مما إذا كان التخصيص مفتوحًا. حاول مرة أخرى بعد قليل.',
  'Only the owner or an admin can ask for this': 'المالك أو مدير النظام فقط يمكنه طلب ذلك',
  'Say what you want to change': 'اذكر ما تريد تغييره',
  'Only Nasq360\'s own team can see this': 'فريق Nasq360 فقط يمكنه رؤية ذلك',
