  'The real system': 'النظام الحقيقي',
  'Dashboards': 'لوحات المتابعة',
  'weeks of cash forecast, built for you': 'أسبوعاً من توقّع النقدية، جاهزة لك',
  'See it before you sign up': 'شاهده قبل أن تسجّل',
  'These are real Nasq360 screens, running a sample trading company. Nothing here is a mock-up.': 'هذه شاشات حقيقية من Nasq360 لشركة تجارية تجريبية. لا شيء هنا تصميم وهمي.',
  'Dashboards that think ahead': 'لوحات متابعة تفكّر قبلك',
  'Your numbers arrive already explained: where cash will be in 13 weeks, which deals will close, and whether the books add up.': 'تصلك أرقامك مشروحة: أين ستكون النقدية بعد ١٣ أسبوعاً، وأي الصفقات ستُغلق، وهل الحسابات متوازنة.',
  'Arabic first': 'العربية أولاً',
  'Truly bilingual, never an afterthought': 'ثنائي اللغة حقاً، وليس ترجمة لاحقة',
  'Every screen mirrors right to left, with Arabic documents and reports. Drag the line to compare.': 'كل شاشة تنعكس من اليمين لليسار، بمستندات وتقارير عربية. اسحب الخط للمقارنة.',
  'Nile Trading · Dashboard': 'النيل للتجارة · لوحة المتابعة',
