  'Consumables pack: 3 left': 'عبوة المستهلكات: باقٍ ٣',
  'Books balanced': 'الحسابات متوازنة',
  'Built from what customers owe, bills due and the way each customer really pays.': 'مبني على مستحقات العملاء والفواتير المستحقة وطريقة سداد كل عميل فعلاً.',
  'Lowest point': 'أدنى نقطة',
  'Checked on every change.': 'تُفحص مع كل تغيير.',
  'Debits equal credits': 'المدين يساوي الدائن',
  'Stock matches its account': 'المخزون يطابق حسابه',
  'Customers match their account': 'العملاء يطابقون حسابهم',
  'Weighted forecast: {amount}': 'التوقّع المرجّح: {amount}',
  'Sales against target': 'المبيعات مقابل المستهدف',
  'Target': 'المستهدف',
  'Ask Nasq360': 'اسأل Nasq360',
  'Questions in plain words, answers from your own books.': 'أسئلة بكلام بسيط، وإجابات من حساباتك أنت.',
  'Cairo Care Hospital owes {amount}, 41 days late. Two invoices are overdue.': 'مستشفى كايرو كير مدين بمبلغ {amount}، متأخر ٤١ يوماً. فاتورتان متأخرتان.',
  'The stock screen in Arabic': 'شاشة المخزون بالعربية',
