  'Compare English and Arabic': 'قارن بين الإنجليزية والعربية',
  'On the phone': 'على الهاتف',
  'Your company in your pocket': 'شركتك في جيبك',
  'Installs from the browser like an app, keeps selling at the counter when the internet drops, and scans barcodes with the camera.': 'يُثبّت من المتصفح كتطبيق، ويواصل البيع في نقطة البيع إذا انقطع الإنترنت، ويقرأ الباركود بالكاميرا.',
  'Installs in one tap': 'يُثبّت بلمسة واحدة',
  'Works offline': 'يعمل بدون إنترنت',
  'Scans barcodes': 'يقرأ الباركود',
  'Company home': 'الصفحة الرئيسية للشركة',
  'Every area of the company on one screen, with what needs you today.': 'كل أقسام الشركة في شاشة واحدة، مع ما يحتاجك اليوم.',
  'Drag deals between stages; values and the forecast update as you go.': 'اسحب الصفقات بين المراحل؛ وتتحدّث القيم والتوقّعات أثناء ذلك.',
  'From draft to paid in three clear steps; the books and the stock update by themselves.': 'من المسودة إلى السداد في ثلاث خطوات واضحة؛ وتتحدّث الحسابات والمخزون تلقائياً.',
  'Quantities and average costs that always match the books, with reorder alerts.': 'كميات ومتوسط تكلفة تطابق الحسابات دائماً، مع تنبيهات إعادة الطلب.',
  'Profit and loss, balance sheet and cash flow, live, with a check that the books balance.': 'الأرباح والخسائر والميزانية والتدفقات النقدية مباشرةً، مع فحص لتوازن الحسابات.',
  'steps from sign-up to a live system': 'خطوات من التسجيل إلى نظام يعمل',
  'Made for you': 'مصمم لك',
  'A system shaped around your industry': 'نظام مفصّل على مجال عملك',
  'Answer a few questions about what you do and Nasq360 matches you with a ready system built for your kind of business: its lists, stages, documents and reports. You see it the moment you sign up.': 'أجب عن بضعة أسئلة عن نشاطك، ويختار لك Nasq360 نظاماً جاهزاً مبنياً لنوع عملك: قوائمه ومراحله ومستنداته وتقاريره. تراه لحظة تسجيلك.',
  'Your industry is already inside': 'مجال عملك موجود بالفعل',
  'Sign up free to see the system ready for your business.': 'سجّل مجاناً لترى النظام الجاهز لعملك.',
  'Choose a picture (JPG, PNG, WebP, GIF…)': 'اختر صورة (JPG أو PNG أو WebP أو GIF…)',
  'Photo changed': 'تم تغيير الصورة',
  'Photo added': 'تمت إضافة الصورة',
  'Kept as a small picture: {w} × {h} px, {kb} KB': 'حُفظت كصورة صغيرة: {w} × {h} بكسل، {kb} كيلوبايت',
  'Photo removed': 'تمت إزالة الصورة',
  'Photo of the product': 'صورة المنتج',
  'Add a photo: choose or drop any picture': 'أضف صورة: اختر أو اسحب أي صورة هنا',
  'No photo yet': 'لا توجد صورة بعد',
  'Making it small…': 'جارٍ تصغيرها…',
  'Change photo': 'غيّر الصورة',
  'Add a photo': 'أضف صورة',
  'Any picture works; it is saved as a small, sharp copy so the company’s data stays light.': 'تصلح أي صورة؛ تُحفظ نسخة صغيرة وواضحة حتى تبقى بيانات الشركة خفيفة.',
  'Save the product first, then add its photo.': 'احفظ المنتج أولاً، ثم أضف صورته.',
  'Only products have a photo': 'الصور للمنتجات فقط',
  'That photo isn’t one of this company’s files': 'هذه الصورة ليست من ملفات هذه الشركة',
  'This picture can’t be opened here. Try a JPG, PNG or WebP (a phone’s HEIC photo can be shared as JPG first).': 'لا يمكن فتح هذه الصورة هنا. جرّب JPG أو PNG أو WebP (يمكن مشاركة صورة HEIC من الهاتف بصيغة JPG أولاً).',
  'This picture is larger than 40 MB: choose a smaller one': 'هذه الصورة أكبر من ٤٠ ميجابايت: اختر صورة أصغر',
  'This browser can’t prepare pictures': 'هذا المتصفح لا يستطيع تجهيز الصور',
  'This picture couldn’t be made small enough. Try another one.': 'تعذّر تصغير هذه الصورة بما يكفي. جرّب صورة أخرى.',
  'added a photo': 'أضاف صورة',
  'changed the photo': 'غيّر الصورة',
  'removed the photo': 'أزال الصورة',
  'matched the existing customer “{a}” by name': 'طابق العميل الموجود «{a}» بالاسم',
  'Overdue bills: {n}': 'فواتير موردين متأخرة: {n}',
  'Save & mark sent': 'احفظ وعلّم كمُرسل',
  'Nothing to show for this period yet: records will appear here as your team works.': 'لا شيء لعرضه في هذه الفترة بعد: ستظهر السجلات هنا مع عمل فريقك.',
  'Next: check it against the supplier’s bill, then press Post. Posting records the cost in the books; the goods are already in stock from the goods received note. After that it can’t be edited, only debited or voided.': 'التالي: راجعها مع فاتورة المورد ثم اضغط ترحيل. الترحيل يسجّل التكلفة في الحسابات؛ والبضاعة دخلت المخزون بالفعل بإذن الاستلام. بعد ذلك لا يمكن تعديلها، فقط إشعار مدين أو إلغاء.',
  'Dashboard ({n})': 'لوحة المتابعة ({n})',
  'closed the task “{a}”: {b} was answered': 'أغلق المهمة «{a}»: تم الرد على {b}',
  'the quotation': 'عرض السعر',
  'Bring your data in, your team, the audit trail and how the system works.': 'إدخال بياناتك، فريقك، سجل التدقيق، وطريقة عمل النظام.',
  '{plan} for {n} people, {cycle}: {amount} (VAT included)': '{plan} لعدد {n} أشخاص، {cycle}: {amount} (شامل ضريبة القيمة المضافة)',
  'Hello Nasq360, we would like to subscribe {company} to {what}.': 'مرحباً Nasq360، نود اشتراك {company} في {what}.',
  'Contact us to subscribe: we turn the plan on as soon as the payment arrives. Paying online is coming soon.': 'تواصل معنا للاشتراك: نفعّل الباقة فور وصول الدفعة. الدفع الإلكتروني قريباً.',
  'Nasq360 subscription: {company}': 'اشتراك Nasq360: {company}',
  'E-mail us': 'راسلنا بالبريد',
  'This quotation was sent, so it can’t be changed. Press Revise to change it and send it again.': 'أُرسل عرض السعر هذا، لذا لا يمكن تغييره. اضغط «مراجعة» لتعديله ثم أرسله مرة أخرى.',
  'The customer accepted this quotation, so it can’t be changed. Make a new quotation for a different offer.': 'وافق العميل على عرض السعر هذا، لذا لا يمكن تغييره. أنشئ عرض سعر جديدًا لعرض مختلف.',
  'This quotation is a confirmed order and can’t be changed.': 'عرض السعر هذا أمر مؤكد ولا يمكن تغييره.',
  'Valid until changed': 'تم تغيير «صالح حتى»',
  'Next: when the goods arrive, enter what came under “Arrived now” and press Receive.': 'التالي: عند وصول البضاعة، أدخل ما وصل في «الواصل الآن» واضغط «استلام».',
  'Closed': 'مغلق',
  'Closed: the rest won’t come. Bill what was received, if not yet billed.': 'مغلق: الباقي لن يصل. اضغط «فوترة ما تم استلامه» إن لم تتم فوترته بعد.',
