  'Do the steps from the top. Each one opens the importer: it checks every row and shows what will happen before anything is saved, and an import can be taken out again.': 'نفّذ الخطوات من الأعلى. كل خطوة تفتح أداة الاستيراد: تفحص كل صف وتعرض ما سيحدث قبل حفظ أي شيء، ويمكن التراجع عن أي استيراد.',
  'Nothing to bring in: everything in these sheets is already in the system.': 'لا شيء لإدخاله: كل ما في هذه الأوراق موجود بالفعل في النظام.',
