  'Each becomes a real document in the books (sales, VAT, stock and what is owed move). Only for documents still being worked on, so nothing is counted twice with the opening balances.': 'يصبح كل منها مستندًا حقيقيًا في الدفاتر (تتحرك المبيعات والضريبة والمخزون والمستحقات). فقط للمستندات التي ما زال العمل عليها جاريًا، حتى لا يُحسب شيء مرتين مع الأرصدة الافتتاحية.',
